/* ECP mockups i18n (vi default, en). Vanilla ES5, no fetch (pages open over file://).
 *
 * Glossary: technical terms kept in English in BOTH languages (en output must use them verbatim; vi copy is never altered):
 *  - Product/modules: MSB Context Platform, Context Platform, ECP, Enterprise Knowledge, Enterprise Search, Ask, Search,
 *    Knowledge Graph, Knowledge Base, KB, Evaluation Lab, Quality Overview, Feedback, Knowledge Gaps, Knowledge Value,
 *    Usage & Retrieval, Serving Performance, Overview, Taxonomy, Ontology, Package Templates,
 *    Transformation Job, Evidence Graph, Document Workspace, Wiki, FAQ, Playbook.
 *  - Roles: Owner, Steward, Admin, System Admin, Viewer.
 *  - Data/AI: triple, entity, relation, node, edge, schema, class, property, chunk, chunking, embedding, vector, index,
 *    retrieval, reranking, RAG, LLM, prompt, citation, source, trace, grounding, hallucination, confidence, score, recall,
 *    precision, latency, p95, golden set, test case, metadata, tag, label (taxonomy sense), artifact, package, template,
 *    pipeline, job, step, OCR, parser.
 *  - Workflow: change request, CR, draft, publish, published, review, migration, rollback, version, diff, baseline, SLA, deep link.
 *  - Formats/IDs: PDF, DOCX, XLSX, URL, API, ID, JSON, CSV, job IDs (TJ-…), CR IDs, file names, version tags (v1.2), Light, Dark.
 * Composite labels translate only the non-glossary part ("Thay đổi & Phê duyệt" → "Changes & Approval",
 * "Quản trị tri thức" → "Knowledge Governance", "Khai thác" → "Explore", "Chất lượng & cải tiến" → "Quality & Improvement").
 * User content (document titles, KB names, people, sample answers/excerpts) is not translated; such nodes carry data-i18n-skip.
 *
 * Markup:
 *   data-i18n="key"                 textContent (leaf elements only)
 *   data-i18n-html="key"            innerHTML (trusted static strings only)
 *   data-i18n-attr="attr:key;…"     aria-label | title | placeholder | alt | aria-description
 *   data-i18n-args='{"n":12}'       {name} interpolation
 *   data-i18n-src                   node whose text JS (re)writes from a vi source string; translated by vi lookup
 *   data-i18n-skip                  sample/user content marker (inert; used by the coverage check)
 * API: ECP_I18N.lang, tr(key, viFallback, args), tv(viText), src(el, viText), apply(root), set(lang), onChange(fn)
 */
(function () {
  var LANGS = { vi: 1, en: 1 }, ATTRS = { 'aria-label': 1, title: 1, placeholder: 1, alt: 1, 'aria-description': 1 };
  var root = document.documentElement;
  var I = window.ECP_I18N = { dict: { en: {}, vi: {} }, lang: 'vi' };
  function store(k, v) { try { if (v === undefined) return localStorage.getItem(k); localStorage.setItem(k, v); } catch (e) { return null; } return null; }
  // ---- language resolution: ?lang → localStorage ecp-lang → vi ----
  function resolve() {
    var q = null;
    try { q = new URLSearchParams(location.search).get('lang'); } catch (e) {}
    if (q && LANGS[q]) { store('ecp-lang', q); return q; }
    var s = store('ecp-lang');
    return s && LANGS[s] ? s : 'vi';
  }
  I.lang = resolve();
  if (root.setAttribute) { root.setAttribute('lang', I.lang); root.setAttribute('data-lang', I.lang); }

  var warned = {};
  function warn(msg) { if (warned[msg]) return; warned[msg] = 1; if (window.console) console.warn('[i18n] ' + msg); }
  function fill(s, args) {
    if (!args) return s;
    return String(s).replace(/\{(\w+)\}/g, function (m, k) { return args[k] !== undefined ? args[k] : m; });
  }
  function lookup(key) {
    var v = I.dict.en[key];
    if (v === undefined) warn('missing ' + key);
    return v;
  }
  // tr: en string for key when lang=en, else the vi fallback; {x} args interpolated in both
  I.tr = function (key, vi, args) {
    if (I.lang === 'en') { var v = lookup(key); if (v !== undefined) return fill(v, args); }
    return fill(vi, args);
  };
  // tv: translate by vi source text (strings JS copies from data-* attributes)
  var rev = null;
  function revIdx() {
    if (rev) return rev;
    rev = {};
    var vi = I.dict.vi;
    for (var k in vi) if (Object.prototype.hasOwnProperty.call(vi, k)) rev[vi[k]] = k;
    return rev;
  }
  function norm(s) { return String(s).replace(/\s+/g, ' ').trim(); }
  I.keyOf = function (viText) { return revIdx()[norm(viText)]; };
  I.tv = function (viText) {
    if (viText === null || viText === undefined) return viText;
    if (I.lang !== 'en') return viText;
    var k = I.keyOf(viText);
    if (!k) return viText;
    var v = I.dict.en[k];
    return v === undefined ? viText : v;
  };
  function keepWs(orig, s) { var m = /^(\s*)[\s\S]*?(\s*)$/.exec(orig); return m[1] + s + m[2]; }
  // src: element whose text JS writes from a vi source string
  // enText (optional) overrides the vi lookup, e.g. a status label taken from a composite "label|class" spec
  function srcText(el) { return I.lang === 'en' && el.__kcEn ? el.__kcEn : I.tv(el.__kcSrc); }
  I.src = function (el, viText, enText) {
    if (!el) return;
    el.__kcSrc = viText; el.__kcEn = enText && enText !== viText ? enText : null;
    if (!el.hasAttribute('data-i18n-src')) el.setAttribute('data-i18n-src', '');
    var t = srcText(el);
    el.textContent = t;
    if (el.hasAttribute('title')) el.setAttribute('title', t);
  };
  function parseArgs(el) {
    var a = el.getAttribute('data-i18n-args');
    if (!a) return null;
    try { return JSON.parse(a); } catch (e) { warn('bad args ' + a); return null; }
  }
  function each(scope, sel, fn) {
    if (scope.nodeType === 1 && scope.matches && scope.matches(sel)) fn(scope);
    var l = scope.querySelectorAll ? scope.querySelectorAll(sel) : [];
    for (var i = 0; i < l.length; i++) fn(l[i]);
  }
  I.apply = function (scope) {
    scope = scope || document;
    var en = I.lang === 'en';
    each(scope, '[data-i18n]', function (el) {
      if (el.__kcVi === undefined) { if (!en) return; el.__kcVi = el.textContent; }
      var v = en ? lookup(el.getAttribute('data-i18n')) : undefined;
      var t = v === undefined ? el.__kcVi : keepWs(el.__kcVi, fill(v, parseArgs(el)));
      if (el.textContent !== t) el.textContent = t;
    });
    each(scope, '[data-i18n-html]', function (el) {
      if (el.__kcViH === undefined) { if (!en) return; el.__kcViH = el.innerHTML; }
      var v = en ? lookup(el.getAttribute('data-i18n-html')) : undefined;
      el.innerHTML = v === undefined ? el.__kcViH : fill(v, parseArgs(el));
    });
    each(scope, '[data-i18n-attr]', function (el) {
      var c = el.__kcViA || (el.__kcViA = {});
      el.getAttribute('data-i18n-attr').split(';').forEach(function (p) {
        var i = p.indexOf(':'); if (i < 0) return;
        var a = p.slice(0, i).trim(), k = p.slice(i + 1).trim();
        if (!ATTRS[a]) { warn('attribute not allowed ' + a); return; }
        if (c[a] === undefined) { if (!en) return; c[a] = el.getAttribute(a); }
        var v = en ? lookup(k) : undefined;
        el.setAttribute(a, v === undefined ? c[a] : fill(v, parseArgs(el)));
      });
    });
    each(scope, '[data-i18n-src]', function (el) {
      if (el.__kcSrc === undefined) el.__kcSrc = el.textContent.trim();
      var t = srcText(el);
      if (el.textContent !== t) el.textContent = t;
      if (el.hasAttribute('title') && el.getAttribute('title') !== t && I.keyOf(el.__kcSrc)) el.setAttribute('title', t);
    });
    each(scope, '[data-lang-switch] button[data-lang]', function (b) {
      b.setAttribute('aria-pressed', String(b.getAttribute('data-lang') === I.lang));
    });
  };
  // ---- truncation: full text as title when an en label is ellipsised ----
  var TRUNC = '.nav-text, .crumb-current, .wz-step > span:not(.wz-num), .jstep-t, .up-row > span:first-child';
  function truncPass() {
    var l = document.querySelectorAll(TRUNC);
    for (var i = 0; i < l.length; i++) {
      var el = l[i], cut = I.lang === 'en' && el.scrollWidth > el.clientWidth + 1;
      if (cut && (!el.hasAttribute('title') || el.hasAttribute('data-i18n-autotitle'))) { el.setAttribute('title', el.textContent.trim()); el.setAttribute('data-i18n-autotitle', ''); }
      else if (!cut && el.hasAttribute('data-i18n-autotitle')) { el.removeAttribute('title'); el.removeAttribute('data-i18n-autotitle'); }
    }
  }
  var subs = [];
  I.onChange = function (fn) { if (typeof fn === 'function') subs.push(fn); };
  function live(msg) {
    var r = document.getElementById('ecp-live');
    if (!r) { r = document.createElement('div'); r.id = 'ecp-live'; r.className = 'sr-only'; r.setAttribute('aria-live', 'polite'); r.setAttribute('role', 'status'); document.body.appendChild(r); }
    r.textContent = '';
    setTimeout(function () { r.textContent = msg; }, 30);
  }
  I.set = function (lang, announce) {
    if (!LANGS[lang]) return;
    I.lang = lang;
    root.setAttribute('lang', lang); root.setAttribute('data-lang', lang);
    store('ecp-lang', lang);
    I.apply(document);
    for (var i = 0; i < subs.length; i++) { try { subs[i](lang); } catch (e) { if (window.console) console.error('[i18n] onChange', e); } }
    truncPass();
    if (announce) live(lang === 'en' ? 'Language: English' : 'Ngôn ngữ: Tiếng Việt');
  };
  // locale formatting for the current language (vi-VN: 48.620 · 91,4% · 16/05/2026; en-US: 48,620 · 91.4% · 05/16/2026)
  function locale() { return I.lang === 'en' ? 'en-US' : 'vi-VN'; }
  I.fmtNum = function (n, opts) { return new Intl.NumberFormat(locale(), opts).format(n); };
  I.fmtDate = function (d, opts) {
    if (!(d instanceof Date)) d = new Date(d);
    return new Intl.DateTimeFormat(locale(), opts || { day: '2-digit', month: '2-digit', year: 'numeric' }).format(d);
  };
  function ready() { root.classList.add('i18n-ready'); }
  setTimeout(ready, 1000);
  document.addEventListener('DOMContentLoaded', function () {
    I.apply(document);
    ready();
    truncPass();
    // content injected later (templates, popover, drawers) gets translated as it appears
    if (window.MutationObserver) {
      new MutationObserver(function (ms) {
        if (I.lang !== 'en') return;
        ms.forEach(function (m) { for (var i = 0; i < m.addedNodes.length; i++) { var n = m.addedNodes[i]; if (n.nodeType === 1) I.apply(n); } });
      }).observe(document.body, { childList: true, subtree: true });
    }
    // language switch (user popover and index top bar)
    document.addEventListener('click', function (e) {
      var b = e.target.closest && e.target.closest('[data-lang-switch] button[data-lang]');
      if (!b) return;
      I.set(b.getAttribute('data-lang'), true);
      b.focus();
    });
    var rt = null;
    window.addEventListener('resize', function () { clearTimeout(rt); rt = setTimeout(truncPass, 150); });
  });
})();

