    "cfg.os.tipStruct": ["Các loại đối tượng (Entity Type) và loại quan hệ (Relationship Type) của tri thức đang chọn.", "The entity types and relationship types of the selected knowledge base."],
    "cfg.os.tipEntTypeSec": ["Loại đối tượng nghiệp vụ như Khách hàng, Khoản vay. Số bên phải là số instance của loại.", "Business object types such as Customer or Loan. The number on the right is how many instances each has."],
    "cfg.os.tipRelTypeSec": ["Cách các loại đối tượng liên kết với nhau. Số bên phải là số liên kết cụ thể (instance).", "How object types link to each other. The number on the right is how many concrete links (instances) each has."],
    "cfg.os.tipInst": ["Instance là giá trị cụ thể của một loại, ví dụ một khách hàng hay một khoản vay cụ thể.", "An instance is a concrete value of a type, such as one specific customer or loan."],
