    "cfg.os.tipColRel": ["Số quan hệ đi vào / đi ra của instance này.", "Incoming / outgoing relationships of this instance."],
    "cfg.os.tipStatus": ["Unverified: chờ xác minh ở Thay đổi & Phê duyệt. Active / Inactive: đang dùng hoặc đã tắt.", "Unverified: waiting to be verified in Changes & Approval. Active / Inactive: in use or switched off."],
    "cfg.os.tipActive": ["Bật: đang sử dụng. Tắt: ngưng sử dụng nhưng dữ liệu vẫn được giữ lại.", "On: in use. Off: no longer used, but the data is kept."],
    "cfg.os.tipStActive": ["Đang được sử dụng. Có thể tắt để ngưng dùng mà không xoá.", "In use. Switch it off to stop using it without deleting it."],
    "cfg.os.tipStUnv": ["Mới thêm, chưa được xác minh ở Thay đổi & Phê duyệt nên chưa bật/tắt được.", "Newly added and not yet verified in Changes & Approval, so it can't be switched on or off yet."],
    "cfg.os.tipStInactive": ["Đã tắt, tạm ngưng sử dụng; dữ liệu vẫn được giữ lại.", "Switched off and not in use; the data is kept."],
    "cfg.os.tipEntType": ["Loại đối tượng nghiệp vụ, ví dụ Khách hàng, Khoản vay; khai báo các thuộc tính chung cho mọi instance.", "A business object type, such as Customer or Loan; it defines the attributes every instance shares."],
    "cfg.os.tipEntInst": ["Một giá trị cụ thể của entity type, ví dụ một khách hàng hay một khoản vay cụ thể.", "One concrete value of an entity type, such as a specific customer or loan."],
    "cfg.os.tipRelType": ["Cách hai loại đối tượng liên kết với nhau, ví dụ Khoản vay được quy định bởi Tài liệu.", "How two object types link, such as a Loan being governed by a Document."],
    "cfg.os.tipRelInst": ["Một liên kết cụ thể giữa hai instance, ví dụ một khoản vay cụ thể được quy định bởi một văn bản cụ thể.", "One concrete link between two instances, such as a specific loan governed by a specific document."],
    "cfg.os.tipAttrType": ["Các trường thông tin mà mọi instance của loại này có, kèm kiểu dữ liệu và có bắt buộc hay không.", "The fields every instance of this type has, with their data type and whether they are required."],
    "cfg.os.tipAttrVals": ["Giá trị cụ thể của từng thuộc tính đã khai báo ở loại tương ứng.", "The actual value of each attribute defined on the type."],
    "cfg.os.tipSteward": ["Người phụ trách nội dung và chất lượng của entity type này.", "The person responsible for the content and quality of this entity type."],
    "cfg.os.tipRelOut": ["Quan hệ mà entity type này là bên nguồn, ví dụ Khoản vay được quy định bởi …", "Relationships where this entity type is the source, such as Loan governed by …"],
    "cfg.os.tipRelIn": ["Quan hệ mà entity type này là bên đích, ví dụ … áp dụng cho Khách hàng.", "Relationships where this entity type is the target, such as … applies to Customer."],
    "cfg.os.tipTags": ["Nhóm tag hoặc tag trong Taxonomy dùng để phân loại entity type này.", "Taxonomy tag groups or tags used to classify this entity type."],
    "cfg.os.tipRelInstList": ["Các liên kết cụ thể giữa instance này và các instance khác.", "The concrete links between this instance and other instances."],
    "cfg.os.tipRelProps": ["Các trường thông tin ghi kèm mỗi liên kết, ví dụ ngày hiệu lực, điều khoản.", "Fields recorded on each link, such as effective date or clause."],
    "cfg.os.tipTriple": ["Từng cặp loại nguồn và loại đích được nối bằng quan hệ này.", "Each source type and target type pair joined by this relationship."],
    "cfg.os.tipTriInst": ["Liên kết cụ thể dạng instance nguồn, quan hệ, instance đích.", "A concrete link: source instance, relationship, target instance."],
    "cfg.os.tipVerLive": ["Phiên bản đã được duyệt và đang được hệ thống sử dụng.", "The approved version the system is using now."],
    "cfg.os.tipVerPending": ["Các thay đổi đã gửi duyệt, đang chờ người duyệt quyết định.", "Changes that were submitted and are waiting for a reviewer."],
    "cfg.os.tipVerDraft": ["Nơi gom các thay đổi; chỉ có hiệu lực sau khi Gửi duyệt và được duyệt.", "Where changes are collected; they take effect only after you submit them and they are approved."],
    "cfg.os.tipSubmit": ["Gom các thay đổi trong Bản nháp thành một yêu cầu để người duyệt phê duyệt.", "Bundle the draft's changes into one request for a reviewer to approve."],
